//       reading(token, conf){},               // live read-out, every frame
//       sign(token, conf, latencyMs){},       // a sign COMMITTED (verbatim path spoke it)
//       ambiguous(top3){},                    // conf 0.55–0.85 -> UI shows choices -> rec.confirm(label)
//       learned(label, count){},              // enrollment / correction stored (chip + counter)
//       spoken(text){},                       // the agent's spoken sentence (YOU caption)
//       caption(text){},                      // hearing party reply (THEM caption)
//       bridge(connected){},                  // bridge ws up/down
//       error(msg){},
